index a018929aa82..8b9a42d16f2 100644
--- a/mailnews/db/panorama/public/nsIFolder.idl
+++ b/mailnews/db/panorama/public/nsIFolder.idl
@@ -69,6 +69,16 @@ interface nsIFolder : nsISupports {
    */
   boolean isAncestorOf(in nsIFolder other);

+  /**
+   * If this folder has a child with the given name.
+   */
+  boolean containsChildNamed(in AUTF8String name);
+
